  const r1 = Math.tanh((act-inh*0.7+bg*0.3+spiral)*2.2);
  const r2 = Math.tanh((act2-inh2*0.6+bg*0.2+pulse)*2.0);
  const cross = Math.tanh((r1*r2*3+r1*0.3+r2*0.3)*1.5);
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const micro = Math.sin(sx*0.4+t*3)*Math.sin(sy*0.35-t*2.5)*Math.sin((sx-sy)*0.2+t*1.8)*0.08;
  const blend = cross*0.5+r1*0.25+r2*0.1+cell*0.1+micro, v = blend*0.5+0.5;
